if (!taskColumns.has('due_date')) db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
if (!taskColumns.has('notes')) db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
